INSERT INTO decisions (id, topic, summary, status, project_id, required_role, decided_at, escalated_at, resolved_at, work_item_id, resolution, decided_by, options) VALUES ('d-otel-vendor', 'Self-hosted OTel collectors over vendor agents', 'Vendor APM agents were quoted per host at about three times the cost of running our own collectors, and each shipped sampling we could not tune. We chose self-hosted OpenTelemetry collectors in an agent and gateway topology, exporting OTLP to the current backend. The cost is owning the fleet: upgrades, memory tuning and the burst OOM are ours to fix. Switching backends stays a config change, not a re-instrumentation.', 'resolved', 'p-observability', NULL, (NOW() - INTERVAL '40 days')::date, NULL, NOW() - INTERVAL '40 days', 'wi-obs-e1', 'Self-hosted OpenTelemetry collectors in an agent and gateway topology, exporting OTLP to the current backend.', 'p-004', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO decision_participants (person_id, decision_id, role) VALUES ('p-004', 'd-otel-vendor', 'decider') ON CONFLICT DO NOTHING;
