INSERT INTO decisions (id, topic, summary, status, project_id, required_role, decided_at, escalated_at, resolved_at, work_item_id, resolution, decided_by, options) VALUES ('d-cognito-cutover', 'Cutover order for legacy SSO tenants', 'Twelve customer tenants remain on the SAML shim, and each moves with the single-tenant cutover runbook. Smallest first keeps the blast radius low while the team learns the runbook. Riskiest first moves the two tenants with custom SAML attribute mappings while the shim is still warm and rollback is a route flip, but a failure there is loud and customer-visible. The order decides who is warned and when, so it is a release call.', 'escalated', 'p-auth-migration', 'org-leader', NULL, NOW() - INTERVAL '2 days', NULL, 'wi-auth-e2-s2', NULL, NULL, '[{"id": "smallest-first", "label": "Smallest tenants first", "detail": "Keeps the blast radius low while the team learns the runbook."}, {"id": "riskiest-first", "label": "Riskiest two tenants first", "detail": "The custom SAML mappings move while the shim is warm and rollback is a route flip."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
