INSERT INTO decisions (id, topic, summary, status, project_id, required_role, decided_at, escalated_at, resolved_at, work_item_id, resolution, decided_by, options) VALUES ('d-eval-judge-model', 'Judge model for canary evaluation', 'The canary judge scores every sampled answer, so its model sets both the evaluation bill and how far the scores can be trusted. On the 120-question pilot set Nova Pro agrees with human labels 82 percent of the time and Nova Lite 71 percent, at about a sixth of the cost per judged answer. Halving the sample rate from 20 to 10 percent would fund Nova Pro at the current spend. Open until the final rubric weights have run on both.', 'open', 'p-llm-platform', NULL, NULL, NULL, NULL, 'wi-llm-e1-s2', NULL, NULL, '[{"id": "nova-pro-10", "label": "Nova Pro, sample rate halved to 10%", "detail": "82 percent agreement with human labels, at the current spend."}, {"id": "nova-lite-20", "label": "Nova Lite at the current 20% sample rate", "detail": "71 percent agreement, at about a sixth of the cost per judged answer."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
