INSERT INTO decisions (id, topic, summary, status, project_id, required_role, decided_at, escalated_at, resolved_at, work_item_id, resolution, decided_by, options) VALUES ('d-iceberg', 'Iceberg over Delta for the lakehouse table format', 'The lakehouse is read by Spark, Trino and Flink, so the table format had to work well in all three. Iceberg''s engine-neutral catalog, hidden partitioning and snapshot isolation fit that roadmap. Delta was faster under Spark in our benchmark but weaker in the other two engines. The consequence: compaction and snapshot expiry are a job we run, not a feature we buy.', 'resolved', 'p-data-lake', NULL, (NOW() - INTERVAL '3 days')::date, NULL, NOW() - INTERVAL '3 days', 'wi-lake-e1', 'Iceberg as the lakehouse table format, for its engine-neutral catalog across Spark, Trino and Flink.', 'p-025', NULL) ON CONFLICT (id) DO NOTHING;
