INSERT INTO decisions (id, topic, summary, status, project_id, required_role, decided_at, escalated_at, resolved_at, work_item_id, resolution, decided_by, options) VALUES ('d-inference-warm-floor', 'Warm floor or scale-to-zero for tier-1 models', 'Tier-1 models scale to zero after 15 minutes idle, and the next request pays a 40 to 90 second cold start against a 2.5-second p99 SLO. A warm floor of one replica per tier-1 model removes the cold start at about $380 a month per model. Baking weights into the image cuts the load to about 20 seconds at no standing cost, but still breaches the SLO. Open until the teams that own the SLO agree what a breach costs them.', 'open', 'p-inference-platform', NULL, NULL, NULL, NULL, 'wi-inf-e1-b3', NULL, NULL, '[{"id": "warm-floor", "label": "Warm floor of one replica per tier-1 model", "detail": "No cold start, at about $380 a month per model."}, {"id": "bake-weights", "label": "Bake weights into the image", "detail": "Loads in about 20 seconds at no standing cost, but still breaches the SLO."}, {"id": "scale-to-zero", "label": "Keep scale-to-zero", "detail": "No standing cost; the 40 to 90 second cold start stays."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO decision_participants (person_id, decision_id, role) VALUES ('p-049', 'd-inference-warm-floor', 'decider') ON CONFLICT DO NOTHING;
INSERT INTO decision_participants (person_id, decision_id, role) VALUES ('p-013', 'd-inference-warm-floor', 'contributor') ON CONFLICT DO NOTHING;
INSERT INTO decision_participants (person_id, decision_id, role) VALUES ('p-043', 'd-inference-warm-floor', 'contributor') ON CONFLICT DO NOTHING;
