INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-1', 'wi-obs-e1-b5', 'p-008', 'Repro: burst 40k spans/s for 90s and the gateway pod OOMs inside 4 minutes. Bounding the queue trades spans for survival — I think we take that trade.', FALSE, NOW() - INTERVAL '12 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-2', 'wi-obs-e1-b5', 'p-004', 'Agreed. Cap the queue and let tail-sampling keep errors; dropped healthy spans are the cheapest loss we have.', FALSE, NOW() - INTERVAL '2 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-3', 'wi-obs-e2-s2', 'p-011', 'Fast-burn window at 5m/1h and slow-burn at 6h/3d, thresholds from the SRE workbook. PR has the recording rules.', FALSE, NOW() - INTERVAL '6 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-4', 'wi-auth-e1-b4', 'p-051', 'The loop is the client retrying refresh on a 403 that is actually a revocation. Server should return a terminal signal, not a retryable one.', FALSE, NOW() - INTERVAL '8 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-5', 'wi-auth-e1-s3', 'p-002', 'Server-side max-age landed behind a flag; flipping it after the cutover window closes.', FALSE, NOW() - INTERVAL '9 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-6', 'wi-llm-e1-s2', 'p-013', 'Rubric weights: grounding 0.4, completeness 0.3, tone 0.15, latency 0.15. Judge agreement with human labels at 0.82 on the pilot set.', FALSE, NOW() - INTERVAL '1 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-7', 'wi-llm-e2-s1', 'p-042', 'Golden sets are versioned with the prompt now — an eval score means nothing if the set drifted under it.', FALSE, NOW() - INTERVAL '1 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-8', 'wi-cost-e2-s2', 'p-017', 'Showback needs the bot baseline broken out separately from interactive runs — maintenance is a floor, not a choice.', FALSE, NOW() - INTERVAL '3 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-9', 'wi-obs-e1-s4', 'p-004', 'Start with low-risk services after the collector rollout.', FALSE, NOW() - INTERVAL '2 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-10', 'wi-obs-e1-s4', 'p-011', 'Keep the bridge available until dashboard parity is verified.', FALSE, NOW() - INTERVAL '1 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-11', 'wi-auth-e1-b4', 'p-002', 'Agreed with Simone. Answer 401 with error="invalid_token" and a session_revoked reason, and the client signs out once. Every other 401 stays retryable with backoff.', FALSE, NOW() - INTERVAL '7 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-12', 'wi-auth-e1-b4', 'p-004', 'Repro is in the PR: revoke the grant, leave the tab open, count refresh calls. Before the fix 31 calls in the first minute, after it exactly one, then the sign-in page.', FALSE, NOW() - INTERVAL '3 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-13', 'wi-auth-e2-s2', 'p-051', 'Looking at the callback-list step now. One ask: make it fail closed. If describe-user-pool-client does not list the tenant origin under CallbackURLs, the flip does not start.', FALSE, NOW() - INTERVAL '54 minutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-14', 'wi-obs-e2-b4', 'p-011', 'The dependency map is about 60 percent derivable from traces: 212 service-to-service edges seen in the last 7 days. The rest are batch jobs and queues that emit no spans, and their owners have to declare them before grouping can trust the map.', FALSE, NOW() - INTERVAL '1 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-15', 'wi-inf-e1-b3', 'p-013', 'Profiled one cold start on the embedding model: 11 s pulling the image, 52 s loading weights from S3, 6 s warming the CUDA graphs. Baking the weights into the image removes most of the 52 s, but the image grows from 4 GB to 11 GB.', FALSE, NOW() - INTERVAL '4 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-16', 'wi-inf-e1-b3', 'p-049', 'Even baked, a cold start is around 20 s against a 2.5 s p99. I have written the warm floor up as a decision so the standing cost is on record before anyone turns it on.', FALSE, NOW() - INTERVAL '3 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-17', 'wi-llm-e1-b3', 'p-042', 'Seen it after every deploy: 43 replicas, 43 GetPrompt calls in the same second, 12 of them throttled. Jitter alone fixes the deploy case. Stale-while-revalidate covers the store being slow.', FALSE, NOW() - INTERVAL '5 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-18', 'wi-cost-e1-s2', 'p-011', 'Checked the encryption keys: the three quiet collections each use their own KMS key, which is why they cannot share OCUs. Re-keying means a reindex, about 40 minutes per collection.', FALSE, NOW() - INTERVAL '2 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-19', 'wi-rta-e1-b3', 'p-019', 'Raising allowed lateness to 5 minutes would hold window state ten times longer. A side output for late events plus an hourly correction job is cheaper and keeps the aggregates honest.', FALSE, NOW() - INTERVAL '4 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO work_item_comments (id, work_item_id, author_id, body, is_system, created_at) VALUES ('wic-prog-20', 'wi-mob-e1-b3', 'p-035', '@Mia Singh do we keep the drawer swipe on Android, or open the drawer from the tab bar only? The back gesture and the swipe start from the same edge, and every fix that keeps both breaks one of them on some devices.', FALSE, NOW() - INTERVAL '3 hours') ON CONFLICT (id) DO NOTHING;
