-- Work-item briefs: title, summary, why-this-matters, blocked reason, next step.
UPDATE work_items SET title = 'Stop duplicate alerts during a dependency outage', summary = 'One failing dependency can trigger forty pages.', description = 'When the shared Postgres connection proxy failed last month, 41 services paged separately within 6 minutes and the on-call engineer spent the first 20 minutes acknowledging duplicates. Alerts should group by the failing dependency, with the affected services listed inside one page.', blocked_reason = 'Waiting on the dependency map.', next_step = 'Confirm the dependency map with Eli Garcia.', next_step_detail = 'The team needs this before choosing how to group duplicate alerts.' WHERE id = 'wi-obs-e2-b4';
UPDATE work_items SET title = 'Decommission the legacy StatsD bridge', summary = 'Move remaining service metrics to OpenTelemetry.', description = 'Nine services still push StatsD through the bridge, which drops packets under load because it is UDP with a 64 KB receive buffer. Each service moves to OTLP through the collector, and every alert that read a StatsD metric reads its OpenTelemetry equivalent before the bridge is switched off.', blocked_reason = NULL, next_step = 'Move billing and notifications first.', next_step_detail = 'Neither has a paging alert on a StatsD metric. Keep the bridge running until dashboard parity is verified for both.' WHERE id = 'wi-obs-e1-s4';
UPDATE work_items SET title = 'Span-metrics connector feeding RED dashboards', summary = 'Derive rate, errors and duration for every service from its spans.', description = 'The span-metrics connector turns every server span into a call counter and a duration histogram per service and route, so dashboards cover services that never wrote a metric. Cardinality is the risk: route labels must be templated, never raw paths.', blocked_reason = NULL, next_step = 'Enable the connector for checkout and search behind an allow-list.', next_step_detail = 'Compare their RED panels against the StatsD dashboards for a week, then widen the list.' WHERE id = 'wi-obs-e1-s3';
UPDATE work_items SET title = 'Collector OOMs under burst ingest when queue is unbounded', summary = 'A 90-second ingest burst kills the gateway collectors because nothing bounds the export queue.', description = 'At 40k spans/s for 90 seconds the gateway pods reach their 2 GiB limit inside 4 minutes and are OOM-killed, dropping every span in flight, errors included. With memory_limiter first in the pipeline and a bounded sending queue the collector refuses data under pressure instead of dying.', blocked_reason = NULL, next_step = 'Replay the burst against the fixed config in staging.', next_step_detail = 'Pass means no OOM kill, the exporter queue stays under capacity, and tail sampling still keeps every error span.' WHERE id = 'wi-obs-e1-b5';
UPDATE work_items SET title = 'Multi-window burn-rate alerts', summary = 'Alert on how fast the error budget burns, not on raw error counts.', description = 'Fast burn pages, slow burn tickets. Page when 2 percent of the 30-day budget burns in 1 hour (14.4x) and ticket at 5 percent in 6 hours (6x), each confirmed by a short window. Thresholds come from the SLO, not from a feel for the error rate.', blocked_reason = NULL, next_step = 'Backtest the recording rules over 30 days of checkout traffic.', next_step_detail = 'They must page for the two real incidents in that window and stay quiet otherwise.' WHERE id = 'wi-obs-e2-s2';
UPDATE work_items SET title = 'Error-budget dashboard per team', summary = 'Make each team''s remaining error budget visible.', description = 'One panel per team: budget remaining, burn over the window, and who owns the service. When a budget is spent, feature work on that service waits for reliability work, and the panel is what makes that conversation short.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-obs-e2-s3';
UPDATE work_items SET title = 'Metric cardinality budgets', summary = 'Define limits before new metrics increase storage costs.', description = 'One team added a user_id label and created 1.2 million active series in a day, doubling the metrics bill for the month. Every service gets a series budget, and CI fails a pull request that adds an unbounded label.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-obs-e3-s1';
UPDATE work_items SET title = 'Tiered log sampling', summary = NULL, description = 'Debug logs are 70 percent of log volume and almost never read. Debug is sampled at 1 in 20, info is kept for 14 days, and audit logs bypass sampling entirely because compliance needs every line.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-obs-e3-s2';
UPDATE work_items SET title = 'Tenant-by-tenant cutover runbook with rollback', summary = 'Sequence the remaining customer tenants off the SAML shim, each with a two-minute way back.', description = 'Each tenant already moves with the single-tenant cutover runbook: pre-flight the Cognito app client, flip the IdP route, watch the login error rate for 15 minutes, and roll back by restoring the shim route. This story writes the order the 12 remaining customer tenants move in and the rollback for each, which waits on the escalated decision "Cutover order for legacy SSO tenants".', blocked_reason = 'Blocked on "Cutover order for legacy SSO tenants", escalated to Sienna Garcia.', next_step = 'Sienna Garcia decides the cutover order.', next_step_detail = 'She decides once the second internal rehearsal passes. Review the proposed callback-list step for the cutover runbook first, so the retry can run.' WHERE id = 'wi-auth-e2-s2';
UPDATE work_items SET title = 'BFF authorization-code + PKCE flow behind the middleware', summary = NULL, description = 'The BFF runs the authorization-code flow with PKCE (S256) against the Cognito hosted UI and keeps the tokens server-side. The browser only holds an HttpOnly, SameSite=Lax session cookie, so a script injected into the page cannot lift a bearer token.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-auth-e1-s1';
UPDATE work_items SET title = 'JWKS verification with kid-rotation handling', summary = NULL, description = 'Access tokens are verified against the cached JWKS by key id. An unknown kid triggers one rate-limited refetch, at most once a minute, before the token is rejected, so a signing-key rotation signs nobody out and a forged kid cannot hammer the endpoint.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-auth-e1-s2';
UPDATE work_items SET title = 'Inventory every consumer still on the SAML shim', summary = NULL, description = 'Every consumer still on the SAML shim, each with an owner: 14 tenants (12 customer, 2 internal), two of them with custom SAML attribute mappings, plus one internal search callback still pointed at the shim. The cutover order needs this list to order.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-auth-e2-s1';
UPDATE work_items SET title = 'Session cookie hardening: max-age, rotation on switch', summary = 'A switched tenant or role stops honouring the old cookie within the refresh window.', description = 'Every tenant or role switch re-mints the cookie and bumps the session epoch. A copy of the pre-switch cookie on another device is refused at its next grants refresh, at most 120 seconds later, without adding a server-side session store.', blocked_reason = NULL, next_step = 'Simone Chang reviews the epoch comparison in the session middleware.', next_step_detail = 'The server-side max-age is in the same pull request behind a flag, which flips after the cutover window closes.' WHERE id = 'wi-auth-e1-s3';
UPDATE work_items SET title = 'Refresh loop when a grant is revoked mid-session', summary = 'A revoked grant must sign the session out once, not loop on refresh.', description = 'When a grant is revoked mid-session the refresh endpoint answers 403, and the client treats every 403 as retryable, so it refreshes every 2 seconds until the tab closes. One revoked user produced 1,800 refresh calls in an hour. Revocation must answer 401 with a reason the client treats as terminal.', blocked_reason = NULL, next_step = 'Return 401 with a session_revoked reason from the refresh endpoint.', next_step_detail = 'Then the client signs out once on that reason. A regression test revokes a grant mid-session and asserts exactly one refresh call.' WHERE id = 'wi-auth-e1-b4';
UPDATE work_items SET title = 'Logout leaves the legacy shim cookie alive', summary = 'Signing out must also clear the SAML shim cookie.', description = 'Signing out clears the BFF session but not the shim session cookie on the legacy domain, so the next visit silently re-authenticates through the shim. Logout has to pass through the shim single-logout endpoint until the shim is deleted.', blocked_reason = NULL, next_step = 'Add the shim single-logout redirect to the BFF logout handler.', next_step_detail = 'Verify in a fresh browser profile that the visit after logout lands on the Cognito hosted UI, not straight back in.' WHERE id = 'wi-auth-e2-b3';
UPDATE work_items SET title = 'LLM-as-judge canary rubric with weighted dimensions', summary = 'Score every canary answer on a weighted rubric so a prompt change is judged, not eyeballed.', description = 'The judge scores grounding, completeness, tone and latency against the retrieved context. On the 120-question pilot set it agrees with human labels 82 percent of the time. Which model judges is the open decision "Judge model for canary evaluation".', blocked_reason = NULL, next_step = 'Nina Rivera decides the judge model.', next_step_detail = 'Run both candidates over the pilot set with the final weights and report agreement and cost per 1,000 judged answers side by side.' WHERE id = 'wi-llm-e1-s2';
UPDATE work_items SET title = 'Prompt cache stampede on TTL expiry under load', summary = 'Every replica refetches its prompt in the same second when the cache expires.', description = 'Replicas cache each prompt for exactly 60 seconds from boot, so after a deploy they expire together and the prompt store throttles at about 40 requests a second. Jittering the TTL and serving the stale prompt while one refresh runs removes the stampede.', blocked_reason = NULL, next_step = 'Add TTL jitter and stale-while-revalidate to the prompt cache.', next_step_detail = 'Load test with 50 replicas restarted at once: zero throttled fetches.' WHERE id = 'wi-llm-e1-b3';
UPDATE work_items SET title = 'Eval harness with golden sets per agent', summary = 'Gate every prompt and model change on a versioned golden set per agent.', description = 'Each agent has 30 to 60 golden questions with expected facts, versioned with the prompt they test. A change merges only when no rubric dimension drops more than 0.03 against the current baseline.', blocked_reason = NULL, next_step = 'Katya Petrov records the golden-set version in the baseline file.', next_step_detail = 'Without it, a score cannot be compared with the one before it.' WHERE id = 'wi-llm-e2-s1';
UPDATE work_items SET title = 'Guardrail regression suite wired into CI', summary = 'Run the guardrail regression set on every pull request that touches a prompt or a guardrail.', description = 'The set holds 200 prompts that must be blocked (prompt injection, PII exfiltration, off-topic requests) and 200 that must pass. A regression in either direction fails the build, because a guardrail that blocks good questions is also broken.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-llm-e2-s2';
UPDATE work_items SET title = 'Batch inference queue for non-interactive workloads', summary = 'Move nightly summarisation and re-embedding off the interactive endpoint.', description = 'Non-interactive jobs share the on-demand quota with users and cause throttling every night around 02:00 UTC. A batch queue with its own concurrency limit takes them off the interactive path.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-llm-e3-s1';
UPDATE work_items SET title = 'OpenSearch OCU floor audit and collection consolidation', summary = 'Justify or merge every OpenSearch Serverless collection holding its own capacity floor.', description = 'Collections share capacity only when they share an encryption key, so each key group bills its own 2-OCU floor whether or not anyone queries it. Three of five collections served fewer than 100 queries last week. Merging them onto the shared key saves about $350 a month per group.', blocked_reason = NULL, next_step = 'Reindex the three quiet collections onto the shared key group.', next_step_detail = 'Switch readers, then delete the old collections after 7 days of zero queries.' WHERE id = 'wi-cost-e1-s2';
UPDATE work_items SET title = 'Tagging policy enforced at deploy time', summary = 'Refuse a deploy that creates an untagged resource.', description = 'Showback is only as good as the tags. A CDK aspect fails synthesis when a taggable resource lacks initiative and owner tags, and the daily sweep lists anything created outside CDK without them.', blocked_reason = NULL, next_step = 'Layla Hassan reviews the exemption list.', next_step_detail = 'Only resources that cannot carry tags are exempt, each with a reason.' WHERE id = 'wi-cost-e2-s1';
UPDATE work_items SET title = 'Per-initiative showback rollup joining agent spend', summary = 'One view per initiative: infrastructure, model tokens and the bot baseline.', description = 'Infrastructure cost comes from tags, model spend from invocation logs and bot spend from the run ledger. Joining the three per initiative per day shows what an initiative actually costs, with the maintenance-bot baseline shown as a floor rather than mixed into interactive work.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-cost-e2-s2';
UPDATE work_items SET title = 'Autoscaling on queue depth instead of CPU', summary = 'Scale replicas on in-flight requests per replica instead of CPU.', description = 'GPU-bound replicas sit at 30 percent CPU while requests queue for seconds, so CPU-based scaling never fires. Target tracking on queue depth reacts to the load users actually feel: 4 in flight per replica, out after 30 seconds sustained, in after 10 minutes.', blocked_reason = NULL, next_step = 'Publish the in-flight metric from the router.', next_step_detail = 'Emit in-flight requests per model every 10 seconds, switch the staging policy over, and replay the last traffic peak.' WHERE id = 'wi-inf-e1-s1';
UPDATE work_items SET title = 'Cold-start p99 breaches SLA after scale-to-zero', summary = 'The first request after scale-to-zero waits 40 to 90 seconds for the model to load.', description = 'Models idle for 15 minutes scale to zero, and the next request pays the container start plus a 7 GB weight load. p99 on the embedding model reached 74 seconds against a 2.5-second SLO. The fix is a warm floor on tier-1 models or a faster load path.', blocked_reason = NULL, next_step = 'Paolo Mancini decides the warm floor for tier-1 models.', next_step_detail = 'A warm replica costs about $380 a month per model on the current instance type. The decision "Warm floor or scale-to-zero for tier-1 models" holds the comparison.' WHERE id = 'wi-inf-e1-b3';
UPDATE work_items SET title = 'Flink checkpoint tuning for sub-minute recovery', summary = 'Recover from a task failure in under 60 seconds.', description = 'Checkpoints take 3 to 4 minutes because the job snapshots 180 GB of keyed state in full each time. Incremental RocksDB checkpoints, plus unaligned checkpoints under backpressure, bring the interval to 30 seconds and recovery under a minute.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-rta-e1-s1';
UPDATE work_items SET title = 'Late events dropped at the watermark boundary', summary = 'Events arriving after the watermark are silently dropped from the hourly aggregates.', description = 'Mobile clients batch events and deliver them up to 4 minutes late, but the watermark allows 30 seconds of lateness, so about 0.6 percent of events miss their window. Late events should go to a side output and be merged by a correction job, not vanish.', blocked_reason = NULL, next_step = NULL, next_step_detail = NULL WHERE id = 'wi-rta-e1-b3';

